 openModal(`<div class="eyebrow admin-modal-eyebrow">ADMIN · INVESTMENT CERTIFICATE</div><h2 id="dialog-title">Send certificate</h2><p>Recipient: <strong>${esc(u.name)}</strong><br>${esc(u.email)}</p><form id="admin-certificate-form" data-member="${esc(id)}"><div class="field"><label for="admin-certificate-file">Certificate file</label><input id="admin-certificate-file" name="certificate" type="file" required accept=".jpg,.jpeg,.png,.webp,.pdf,application/pdf,image/jpeg,image/png,image/webp"><small>JPG, PNG, WEBP, or PDF · maximum 10 MB.</small></div><div class="field"><label for="admin-certificate-holder">Certificate holder</label><input id="admin-certificate-holder" name="holder_name" value="${esc(u.name)}" required maxlength="120"></div><div class="field"><label for="admin-certificate-number">Certificate number</label><input id="admin-certificate-number" name="certificate_number" value="MT-" required maxlength="80" placeholder="MT-0038419"></div><div class="field"><label for="admin-certificate-plan">Selected plan</label><input id="admin-certificate-plan" name="plan_name" value="${esc(plans[0]?.name||'')}" required maxlength="120" placeholder="Mom’s Select"></div><div class="field"><label for="admin-certificate-date">Date indicated</label><input id="admin-certificate-date" name="indicated_date" type="date" value="${today}" required></div><div class="field"><label for="admin-certificate-sender">Sender name</label><input id="admin-certificate-sender" name="sender_name" value="Francis" required maxlength="80"></div><p class="admin-form-notice">The uploaded file will be attached and, for supported images, shown in the email. A permanent record will be added to this member account.</p><div class="form-message" role="alert"></div><button class="btn btn-primary" type="submit">Send certificate ${I('arrow')}</button></form>`);
