function showAdminMoneyReview(form,data){
 const amount=moneyCents(data.amount),kind=form.dataset.kind,p=plans.find(x=>x.id===data.plan),account=cachedAdminMember(form.dataset.member);
 if(amount<10000||amount>100000000)throw new Error('Enter an amount between ₱100 and ₱1,000,000.');if(kind==='plan'&&(!p||amount<p.min))throw new Error(`This plan starts at ${short(p?.min||500000)}.`);if(data.note.trim().length<3)throw new Error('Enter a reason of at least 3 characters.');
 form.querySelector('.admin-form-fields').hidden=true;const review=form.querySelector('#admin-operation-review');review.hidden=false;form.dataset.stage='confirm';review.innerHTML=`<h3 tabindex="-1">Check the details before confirming.</h3><dl class="admin-confirm-details"><div><dt>Member</dt><dd>${esc(account.user.name)}</dd></div><div><dt>${kind==='plan'?'Plan principal':'Wallet credit'}</dt><dd>${cash(amount)}</dd></div>${kind==='plan'?`<div><dt>Plan</dt><dd>${esc(p.name)}</dd></div><div><dt>Rate and term</dt><dd>${rateLabel(p.rateBps)} daily · ${p.days} days</dd></div><div><dt>Daily interest</dt><dd>${cash(dailyInterestCents(amount,p.rateBps))}</dd></div>`:''}<div><dt>Reason</dt><dd>${esc(data.note.trim())}</dd></div></dl><p class="admin-form-notice">This creates an internal ledger record. Confirm only after checking the member and amount.</p><button type="button" class="btn btn-outline" data-action="admin-edit-operation">${I('back')}Go back and edit</button><button class="btn btn-dark" type="submit">Confirm ${kind==='plan'?'plan assignment':'wallet credit'} ${I('check')}</button>`;review.querySelector('h3').focus();
}
function restoreAdminMoneyForm(form){form.dataset.stage='edit';form.querySelector('.admin-form-fields').hidden=false;form.querySelector('#admin-operation-review').hidden=true;}
function openAdminReview(id){
 if(!isPortalAdmin())return;const r=cachedAdminRequest(id);if(!r)throw new Error('Request not found.');
 const destination=r.withdrawal_destination;
 const payoutDetails=r.type==='withdraw'?`<div><dt>Withdrawal account</dt><dd>${destination?`${destination.type==='e_wallet'?'E-wallet':'Bank'} · ${esc(destination.provider)}<small>${esc(destination.account_holder)} · ${esc(destination.account_number)}</small>`:'No payout details were saved with this request.'}</dd></div>`:'';
 openModal(`<div class="eyebrow admin-modal-eyebrow">${esc(r.reference)}</div><h2 id="dialog-title">${r.type==='deposit'?'Deposit':'Withdrawal'} request</h2><dl class="admin-confirm-details"><div><dt>Member</dt><dd>${esc(r.user.name)}<small>${esc(r.user.email)}</small></dd></div><div><dt>Amount</dt><dd>${cash(r.amount)}</dd></div><div><dt>Submitted</dt><dd>${portalDate(r.created_at)}</dd></div>${payoutDetails}<div><dt>Status</dt><dd>${statusBadge(r.status)}</dd></div><div><dt>Member note</dt><dd>${esc(r.member_note||'No note provided')}</dd></div></dl>${r.status==='pending'&&adminFinancialEnabled()?`<form id="admin-review-form" data-id="${esc(id)}"><div class="field"><label for="admin-decision">Your decision</label><select name="decision" id="admin-decision" required><option value="">Select a decision</option><option value="approve">Approve this request</option><option value="reject">Reject this request</option></select></div><div class="field"><label for="admin-review-note">Review note (visible to the member)</label><textarea id="admin-review-note" name="note" rows="3" required minlength="3" maxlength="500" placeholder="Explain your decision briefly"></textarea></div><p class="admin-form-notice">${r.type==='deposit'?'Approving credits the internal wallet. Rejecting leaves the balance unchanged.':'The amount is already reserved. Approval completes the withdrawal record; rejection returns it to the available balance.'} No real payment is processed.</p><div class="form-message" role="alert"></div><button type="submit" class="btn btn-primary">Confirm decision ${I('check')}</button></form>`:`<p class="admin-form-notice">${esc(r.review_note||'Wallet operations are disabled.')}</p><button class="btn btn-outline" data-action="close">Close</button>`}`);
}
function adminOperationReceipt(title,message,amount,recipient){openModal(`<div class="admin-receipt-icon">${I('check')}</div><h2 id="dialog-title">${esc(title)}</h2><p>${esc(message)}</p>${amount?`<dl class="admin-confirm-details"><div><dt>Amount</dt><dd>${cash(amount)}</dd></div><div><dt>Member</dt><dd>${esc(recipient)}</dd></div></dl>`:''}<p class="admin-form-notice">The action is recorded in the activity log. No real payment was sent.</p><button class="btn btn-dark" data-action="close">Done ${I('check')}</button>`);}
document.addEventListener('click',async e=>{
 const control=e.target.closest('[data-action]');if(!control)return;const action=control.dataset.action;if(!action.startsWith('admin-'))return;e.preventDefault();e.stopImmediatePropagation();if(!isPortalAdmin())return;
 try{
  if(action==='admin-home'){closeModal();go('admin');}
  if(action==='admin-refresh'){clearAdminCache();render();}
  if(action==='admin-send-funds')openAdminSend(control.dataset.id,'funds');
  if(action==='admin-send-plan')openAdminSend(control.dataset.id,'plan');
  if(action==='admin-stop-plan')openAdminStopPlan(control.dataset.userId,control.dataset.allocationId);
  if(action==='admin-upgrade-plan')openAdminUpgradePlan(control.dataset.userId,control.dataset.allocationId);
  if(action==='admin-send-certificate')openAdminCertificate(control.dataset.id);
  if(action==='admin-review')openAdminReview(control.dataset.id);
  if(action==='admin-toggle-member-section'){
   const detail=control.closest('.admin-member-detail'),panel=detail&&document.getElementById(control.getAttribute('aria-controls'));
   if(!detail||!panel||!detail.contains(panel))return;
   detail.querySelectorAll('.admin-member-section-panel').forEach(section=>section.hidden=true);
   detail.querySelectorAll('.admin-member-section-button').forEach(button=>button.setAttribute('aria-expanded','false'));
   control.setAttribute('aria-expanded','true');panel.hidden=false;
  }
  if(action==='admin-member-request-filter'){
   const group=control.closest('[data-request-group]'),status=control.dataset.status;
   if(!group||!['pending','approved'].includes(status))return;
   group.parentElement.querySelectorAll('[data-request-status-panel]').forEach(panel=>{panel.hidden=panel.dataset.requestStatusPanel!==status;});
   group.querySelectorAll('[data-action="admin-member-request-filter"]').forEach(button=>{
    const active=button===control;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active));
   });
  }
  if(action==='admin-copy-referral'){const code=control.dataset.referralCode;if(!code)throw new Error('This member does not have a referral link.');if(!navigator.clipboard?.writeText)throw new Error('Clipboard access is unavailable in this browser.');const link=control.dataset.previewType==='special'?specialReferralUrl(code):referralUrl(code);await navigator.clipboard.writeText(link);toast('Member referral link copied.');}
  if(action==='admin-set-referral-preview'){const userId=control.dataset.id,previewType=control.dataset.previewType;if(!userId||!['standard','special'].includes(previewType))throw new Error('Choose a valid referral preview for this member.');control.disabled=true;try{const result=await api('admin/users/'+encodeURIComponent(userId)+'/referral-preview','POST',{preview_type:previewType});clearAdminCache();closeModal();render();toast(result.message);}finally{control.disabled=false;}}
  if(action==='admin-edit-operation'){const form=control.closest('form');restoreAdminMoneyForm(form);form.querySelector('[name=amount]').focus();}
 }catch(err){toast(err.message);}
},true);
document.addEventListener('click',event=>{const name=event.target.closest('a[data-member-classify]');if(!name||!isPortalAdmin()||event.button!==0||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey||event.detail===0)return;event.preventDefault();if(event.detail===1){clearTimeout(adminMemberNameClickTimer);adminMemberNameClickTimer=setTimeout(()=>{location.hash=name.hash.slice(1);adminMemberNameClickTimer=undefined;},300);}else if(event.detail===2){clearTimeout(adminMemberNameClickTimer);adminMemberNameClickTimer=undefined;}},true);
document.addEventListener('dblclick',event=>{const name=event.target.closest('[data-member-classify]');if(!name||!isPortalAdmin())return;event.preventDefault();openAdminClassification(name.dataset.memberClassify);});
document.addEventListener('submit',async e=>{const form=e.target;if(form.id==='admin-search-form'){e.preventDefault();e.stopImmediatePropagation();location.hash=adminLink('members',{search:form.elements.search.value.trim()}).slice(1);return;}if(!['admin-money-form','admin-review-form','admin-classify-form','admin-label-form','admin-certificate-form','admin-stop-plan-form','admin-upgrade-plan-form'].includes(form.id))return;e.preventDefault();e.stopImmediatePropagation();if(!isPortalAdmin()||isLoading)return;const data=Object.fromEntries(new FormData(form));
 try{if(form.id==='admin-money-form'&&form.dataset.stage!=='confirm'){showAdminMoneyReview(form,data);return;}
 isLoading=true;form.querySelectorAll('button[type=submit]').forEach(b=>b.disabled=true);
 if(form.id==='admin-label-form'){const result=await api('admin/users/'+encodeURIComponent(form.dataset.id)+'/label','POST',{label:data.label});clearAdminCache();closeModal();render();toast(result.message);}
 else if(form.id==='admin-certificate-form'){const formData=new FormData(form);const result=await api('admin/users/'+encodeURIComponent(form.dataset.member)+'/certificates','POST',formData);clearAdminCache();closeModal();render();toast(result.message);}
 else if(form.id==='admin-stop-plan-form'){const result=await api('admin/users/'+encodeURIComponent(form.dataset.userId)+'/plans/'+encodeURIComponent(form.dataset.allocationId)+'/stop','POST',data);clearAdminCache();closeModal();render();toast(result.message);}
 else if(form.id==='admin-upgrade-plan-form'){const result=await api('admin/users/'+encodeURIComponent(form.dataset.userId)+'/plans/'+encodeURIComponent(form.dataset.allocationId)+'/upgrade','POST',data);clearAdminCache();closeModal();render();toast(result.message);}
 else if(form.id==='admin-classify-form'){const result=await api('admin/users/'+encodeURIComponent(form.dataset.id)+'/classification','POST',data);clearAdminCache();closeModal();render();toast(result.message);}
 else if(form.id==='admin-money-form'){const account=cachedAdminMember(form.dataset.member),kind=form.dataset.kind,amount=moneyCents(data.amount),result=await api('admin/users/'+encodeURIComponent(form.dataset.member)+'/'+(kind==='plan'?'plans':'funds'),'POST',{...data,request_id:form.dataset.requestId});clearAdminCache();closeModal();render();const notice=result.notification_queued===true?'A phone notification was queued. Delivery depends on the queue worker and the member’s device settings.':result.notification_queued===false?'No phone notification was queued. Check the member’s notification subscription and VAPID configuration.':'This action was already processed; no new phone notification was queued.';adminOperationReceipt(kind==='plan'?'Plan assigned.':'Funds sent.',`${kind==='plan'?'The member’s plan is active.':'The member’s internal wallet was credited.'} ${notice}`,amount,account.user.name);}
 else{const request=cachedAdminRequest(form.dataset.id);await api('admin/requests/'+encodeURIComponent(form.dataset.id)+'/review','POST',data);clearAdminCache();closeModal();render();adminOperationReceipt(data.decision==='approve'?'Request approved.':'Request rejected.','The member can see the decision and your review note.',request.amount,request.user.name);}
 }catch(err){if(form.id==='admin-money-form'&&form.dataset.stage==='confirm')restoreAdminMoneyForm(form);errorIn(form,err.message);}finally{isLoading=false;form.querySelectorAll('button[type=submit]').forEach(b=>b.disabled=false);}
},true);

window.addEventListener('hashchange',clearAdminCache);
let adminPresenceRefreshInFlight=false;
window.setInterval(async()=>{
 const r=adminRoute();
 if(document.hidden||route()!=='admin'||r.tab!=='members'||r.user||!isPortalAdmin()||currentModal||isLoading||adminPresenceRefreshInFlight)return;
 const key=adminResource(r);
 if(!adminPageCache.get(key)?.data)return;
 const actor=state.user.id;
 adminPresenceRefreshInFlight=true;
 try{
  const data=await api('admin/'+key);
  if(!isPortalAdmin()||state.user.id!==actor)return;
  adminPageCache.set(key,{data});
  if(route()==='admin'&&adminResource()===key)render();
 }catch(error){console.error('Admin member presence refresh failed.',error);}
 finally{adminPresenceRefreshInFlight=false;}
},30000);
document.addEventListener('change',event=>{if(event.target.id==='admin-plan'){const p=plans.find(v=>v.id===event.target.value);const amount=document.getElementById('admin-amount');if(p&&moneyCents(amount.value)<p.min)amount.value=String(p.min/100);}});
